 use vstd::prelude::*;
 #[cfg(verus_keep_ghost)]
 include!("pde.spec.rs");
 #[cfg(verus_keep_ghost)]
 include!("pde.proof.rs");

 use crate::{
     mem::paging::TableEntry,
