struct VerusVerifyVisitor {
    verify_const: bool,
}

fn get_verus_spec(attrs: &[syn::Attribute]) -> Option<&syn::Attribute> {
    attrs.iter().find(|attr| attr.path().get_ident().map_or(false, |ident| ident == VERUS_SPEC))
}

